"""Python source for the admin/manage_std.html page template."""

TEMPLATE_SOURCE = '<!DOCTYPE html>\n<html lang="en">\n\n<head>\n\n    <meta charset="UTF-8">\n\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n\n    <title>Manage Students - SectionSync</title>\n\n    <style>\n\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n            font-family: Arial, sans-serif;\n        }\n\n        body {\n            background: #f4f6fa;\n            color: #18345d;\n        }\n\n\n        /* TOP HEADER */\n\n        .header {\n            height: 76px;\n\n            background: white;\n\n            border-bottom: 1px solid #dfe3ea;\n\n            display: flex;\n\n            align-items: center;\n\n            justify-content: space-between;\n\n            padding: 0 35px;\n        }\n\n        .header h1 {\n            font-size: 26px;\n\n            color: #15365f;\n        }\n\n        .header-right {\n            font-size: 14px;\n\n            color: #15365f;\n        }\n\n        .header-right span {\n            margin: 0 10px;\n\n            color: #777;\n        }\n\n\n        /* MAIN */\n\n        .main {\n            padding: 30px;\n\n            max-width: 1400px;\n\n            margin: auto;\n        }\n\n\n        /* PAGE HEADING */\n\n        .page-heading {\n            display: flex;\n\n            justify-content: space-between;\n\n            align-items: center;\n\n            margin-bottom: 25px;\n        }\n\n        .page-heading h2 {\n            font-size: 24px;\n\n            margin-bottom: 6px;\n        }\n\n        .page-heading p {\n            color: #64748b;\n\n            font-size: 15px;\n        }\n\n\n        /* UPLOAD BUTTON */\n\n        .upload-btn,\n        .back-btn {\n            background: #2874d8;\n\n            color: white;\n\n            text-decoration: none;\n\n            padding: 12px 20px;\n\n            border-radius: 8px;\n\n            font-size: 14px;\n\n            font-weight: 600;\n        }\n\n        .upload-btn:hover,\n        .back-btn:hover {\n            background: #1f63bd;\n        }\n\n        .heading-actions {\n            display: flex;\n            align-items: center;\n            gap: 10px;\n        }\n        \n        {% if message %}\n        <div style="background:#eaf2ff; padding:14px;\n                border-radius:8px; margin-bottom:18px;">\n        {{ message }}\n        </div>\n        {% endif %}\n\n        {% if upload_errors %}\n        <div style="background:#fff0f0; padding:14px;\n                border-radius:8px; margin-bottom:18px;">\n        <strong>Rows requiring attention:</strong>\n        <ul>\n            {% for error in upload_errors %}\n                <li>{{ error }}</li>\n            {% endfor %}\n        </ul>\n        </div>\n        {% endif %}\n\n\n        /* SEARCH AREA */\n\n        .search-card {\n            background: white;\n\n            border: 1px solid #dfe3ea;\n\n            border-radius: 10px;\n\n            padding: 18px;\n\n            margin-bottom: 20px;\n        }\n\n        .search-form {\n            display: flex;\n\n            gap: 12px;\n\n            align-items: center;\n        }\n\n        .search-input {\n            width: 320px;\n\n            padding: 11px 13px;\n\n            border: 1px solid #cfd6e0;\n\n            border-radius: 7px;\n\n            font-size: 14px;\n\n            outline: none;\n        }\n\n        .search-input:focus {\n            border-color: #2874d8;\n        }\n\n        .program-select {\n            padding: 11px 13px;\n\n            border: 1px solid #cfd6e0;\n\n            border-radius: 7px;\n\n            font-size: 14px;\n\n            background: white;\n\n            min-width: 130px;\n        }\n\n        .search-button {\n            background: #17375e;\n\n            color: white;\n\n            border: none;\n\n            padding: 11px 20px;\n\n            border-radius: 7px;\n\n            font-size: 14px;\n\n            cursor: pointer;\n        }\n\n        .search-button:hover {\n            background: #102c4d;\n        }\n\n\n        /* TABLE */\n\n        .table-container {\n            background: white;\n\n            border: 1px solid #dfe3ea;\n\n            border-radius: 10px;\n\n            overflow-x: auto;\n        }\n\n        table {\n            width: 100%;\n\n            border-collapse: collapse;\n\n            min-width: 950px;\n        }\n\n        thead {\n            background: #f5f7fa;\n        }\n\n        th {\n            text-align: left;\n\n            padding: 15px;\n\n            font-size: 13px;\n\n            color: #17375e;\n\n            font-weight: 600;\n\n            border-bottom: 1px solid #dfe3ea;\n\n            white-space: nowrap;\n        }\n\n        td {\n            padding: 15px;\n\n            font-size: 14px;\n\n            color: #17375e;\n\n            border-bottom: 1px solid #e8ebef;\n\n            white-space: nowrap;\n        }\n\n        tbody tr:hover {\n            background: #fafbfc;\n        }\n\n\n        /* STATUS */\n\n        .status {\n            display: inline-block;\n\n            padding: 6px 11px;\n\n            border-radius: 20px;\n\n            font-size: 12px;\n\n            font-weight: 600;\n        }\n\n        .verified {\n            background: #dff5e8;\n\n            color: #159447;\n        }\n\n        .pending {\n            background: #fff0d4;\n\n            color: #d98900;\n        }\n\n        .not-verified {\n            background: #ffe1e1;\n\n            color: #d93636;\n        }\n\n\n        /* ACTION BUTTONS */\n\n        .edit-btn {\n            background: #e5edff;\n\n            color: #2864c7;\n\n            border: none;\n\n            padding: 8px 13px;\n\n            border-radius: 6px;\n\n            text-decoration: none;\n\n            font-size: 13px;\n\n            margin-right: 5px;\n        }\n\n        .edit-btn:hover {\n            background: #d7e4ff;\n        }\n\n        .delete-btn {\n            background: #ffe3e3;\n\n            color: #e93636;\n\n            border: none;\n\n            padding: 8px 13px;\n\n            border-radius: 6px;\n\n            font-size: 13px;\n\n            cursor: pointer;\n        }\n\n        .delete-btn:hover {\n            background: #ffd3d3;\n        }\n\n\n        /* EMPTY */\n\n        .empty {\n            text-align: center;\n\n            padding: 45px;\n\n            color: #7b8798;\n\n            font-size: 14px;\n        }\n\n\n        /* RESPONSIVE */\n\n        @media (max-width: 700px) {\n\n            .header {\n                padding: 0 18px;\n            }\n\n            .header h1 {\n                font-size: 21px;\n            }\n\n            .header-right {\n                font-size: 12px;\n            }\n\n            .main {\n                padding: 20px;\n            }\n\n            .page-heading {\n                align-items: flex-start;\n\n                gap: 15px;\n            }\n\n            .heading-actions {\n                flex-wrap: wrap;\n            }\n\n            .search-form {\n                flex-wrap: wrap;\n            }\n\n            .search-input {\n                width: 100%;\n            }\n\n        }\n\n    </style>\n\n</head>\n\n\n<body>\n\n\n    <!-- HEADER -->\n\n    <div class="header">\n\n        <h1>\n            Manage Students\n        </h1>\n\n        <div class="header-right">\n\n            Admin\n\n            <span>|</span>\n\n            SectionSync\n\n        </div>\n\n    </div>\n\n\n\n    <!-- MAIN -->\n\n    <div class="main">\n\n\n        <!-- PAGE HEADING -->\n\n        <div class="page-heading">\n\n            <div>\n\n                <h2>\n                    Student Management\n                </h2>\n\n                <p>\n                    View, edit and manage registered students. Include a <strong>cgpa</strong> column in Excel or enter CGPA when editing a student to include them in final allocation.\n                </p>\n\n            </div>\n\n\n            \n            \n<div class="heading-actions">\n<a href="{{ url_for(\'admin_dashboard\') }}" class="back-btn">Back to Dashboard</a>\n\n<form\n    method="POST"\n    action="{{ url_for(\'student_management\') }}"\n    enctype="multipart/form-data"\n    id="excelUploadForm"\n>\n    <input\n        type="file"\n        name="excel_file"\n        id="excelFile"\n        accept=".xlsx"\n        required\n        hidden\n    >\n            \n\n    <button type="button" class="upload-btn"\n            onclick="document.getElementById(\'excelFile\').click()">\n        📁 Upload Excel\n    </button>\n</form>\n</div>\n\n<script>\n    document.getElementById("excelFile").addEventListener(\n        "change",\n        function () {\n            if (this.files.length > 0) {\n                document.getElementById("excelUploadForm").submit();\n            }\n        }\n    );\n</script>\n\n\n\n        </div>\n\n\n\n        <!-- SEARCH -->\n\n        <div class="search-card">\n\n            <form\n                method="GET"\n                action="/admin/student-management"\n                class="search-form"\n            >\n\n                <input\n                    type="text"\n                    name="search"\n                    class="search-input"\n                    placeholder="Search by enrollment number or name..."\n                    value="{{ search }}"\n                >\n\n\n                <select\n                    name="program"\n                    class="program-select"\n                >\n\n                    <option value="">\n                        All Programs\n                    </option>\n\n                    <option\n                        value="CSE"\n                        {% if program == "CSE" %}selected{% endif %}\n                    >\n                        CSE\n                    </option>\n\n                    <option\n                        value="AI&DS"\n                        {% if program == "AI&DS" %}selected{% endif %}\n                    >\n                        AI & DS\n                    </option>\n\n                    <option\n                        value="AI&ML"\n                        {% if program == "AI&ML" %}selected{% endif %}\n                    >\n                        AI & ML\n                    </option>\n\n                    <option\n                        value="AI"\n                        {% if program == "AI" %}selected{% endif %}\n                    >\n                        AI\n                    </option>\n\n                    <option\n                        value="EEE"\n                        {% if program == "EEE" %}selected{% endif %}\n                    >\n                        EEE\n                    </option>\n\n                    <option\n                        value="ECE"\n                        {% if program == "ECE" %}selected{% endif %}\n                    >\n                        ECE\n                    </option>\n\n                </select>\n\n\n                <button\n                    type="submit"\n                    class="search-button"\n                >\n                    Search\n                </button>\n\n            </form>\n\n        </div>\n\n\n\n        <!-- STUDENT TABLE -->\n\n        <div class="table-container">\n\n            {% if students %}\n\n            <table>\n\n                <thead>\n\n                    <tr>\n\n                        <th>\n                            Enrollment No.\n                        </th>\n\n                        <th>\n                            Student Name\n                        </th>\n\n                        <th>\n                            Program\n                        </th>\n\n                        <th>\n                            CGPA\n                        </th>\n\n                        <th>\n                            Fee Status\n                        </th>\n\n                        <th>\n                            Allocation\n                        </th>\n\n                        <th>\n                            Actions\n                        </th>\n\n                    </tr>\n\n                </thead>\n\n\n                <tbody>\n\n                    {% for student in students %}\n\n                    <tr>\n\n                        <td>\n                            {{ student["enrollment_no"] }}\n                        </td>\n\n\n                        <td>\n                            {{ student["student_name"] }}\n                        </td>\n\n\n                        <td>\n                            {{ student["program"] }}\n                        </td>\n\n\n                        <td>\n                            {{ student["cgpa"] if student["cgpa"] else "—" }}\n                        </td>\n\n\n                        <td>\n\n                            {% if student["fee_status"] == "Verified" %}\n\n                                <span class="status verified">\n                                    Verified\n                                </span>\n\n                            {% elif student["fee_status"] == "Pending" %}\n\n                                <span class="status pending">\n                                    Pending\n                                </span>\n\n                            {% else %}\n\n                                <span class="status not-verified">\n                                    Not Verified\n                                </span>\n\n                            {% endif %}\n\n                        </td>\n\n\n                        <td>\n                            {{ student["allocation"] if student["allocation"] else "Not Allocated" }}\n                        </td>\n\n\n                        <td>\n\n                           <a href="{{ url_for(\'edit_student\', student_id=student[\'id\']) }}"\n   class="edit-button">\n    Edit\n</a>\n\n<form\n    method="POST"\n    action="{{ url_for(\'delete_student\', student_id=student[\'id\']) }}"\n    style="display: inline;"\n    onsubmit="return confirm(\'Are you sure you want to delete this student?\');"\n>\n    <button type="submit" class="delete-btn">\n        Delete\n    </button>\n</form>\n\n                        </td>\n\n                    </tr>\n\n                    {% endfor %}\n\n                </tbody>\n\n            </table>\n\n\n            {% else %}\n\n            <div class="empty">\n\n                No students found.\n\n            </div>\n\n            {% endif %}\n\n        </div>\n\n\n    </div>\n\n\n</body>\n\n</html>\n'
